   * ---------------------------------------------------------
   * HOTSPOT
   * ---------------------------------------------------------
   */

  .hotspot {
    position: absolute;

    top: calc(var(--y) * 1%);
    left: calc(var(--x) * 1%);

    width: 40px;
    height: 40px;

    transform: translate(-50%, -50%);

    cursor: pointer;
  }


  /*
   * ---------------------------------------------------------
   * HOTSPOT LABEL - BASE
   * ---------------------------------------------------------
   */

  .hotspot-label {
    position: absolute;

    background: rgba(0, 0, 0, 0.75);
    color: #fff;

    padding: 6px 10px;

    border-radius: 4px;

    font-size: 12px;

    white-space: nowrap;

    opacity: 0;

    pointer-events: none;

    z-index: 10;

    transition:
      opacity 0.25s ease,
      transform 0.25s ease;

    /*
     * Default = top
     */
    top: auto;
    right: auto;
    bottom: 120%;
    left: 50%;

    transform:
      translateX(-50%)
      translateY(5px);

    @media (min-width: 768px) and (max-width: 1200px),
      (max-width: 767px) {

      display: none !important;
    }
  }


  /*
   * ---------------------------------------------------------
   * LABEL - TOP
   * ---------------------------------------------------------
   */

  .hotspot.label-top .hotspot-label {

    top: auto;
    right: auto;
    bottom: 120%;
    left: 50%;

    transform:
      translateX(-50%)
      translateY(5px);
  }


  /*
   * ---------------------------------------------------------
   * LABEL - BOTTOM
   * ---------------------------------------------------------
   */

  .hotspot.label-bottom .hotspot-label {

    top: 120%;
    right: auto;
    bottom: auto;
    left: 50%;

    transform:
      translateX(-50%)
      translateY(-5px);
  }


  /*
   * ---------------------------------------------------------
   * LABEL - LEFT
   * ---------------------------------------------------------
   */

  .hotspot.label-left .hotspot-label {

    top: 50%;
    right: 120%;
    bottom: auto;
    left: auto;

    transform:
      translateY(-50%)
      translateX(5px);
  }


  /*
   * ---------------------------------------------------------
   * LABEL - RIGHT
   * ---------------------------------------------------------
   */

  .hotspot.label-right .hotspot-label {

    top: 50%;
    right: auto;
    bottom: auto;
    left: 120%;

    transform:
      translateY(-50%)
      translateX(-5px);
  }


  /*
   * ---------------------------------------------------------
   * LABEL HOVER
   * ---------------------------------------------------------
   */

  .hotspot:hover .hotspot-label {
    opacity: 1;
  }


  .hotspot.label-top:hover .hotspot-label {
    transform:
      translateX(-50%)
      translateY(0);
  }


  .hotspot.label-bottom:hover .hotspot-label {
    transform:
      translateX(-50%)
      translateY(0);
  }


  .hotspot.label-left:hover .hotspot-label {
    transform:
      translateY(-50%)
      translateX(0);
  }


  .hotspot.label-right:hover .hotspot-label {
    transform:
      translateY(-50%)
      translateX(0);
  }


  /*
   * ---------------------------------------------------------
   * HOTSPOT ACTIVE
   * ---------------------------------------------------------
   */

  .hotspot.active::after {
    transform:
      translate(-50%, -50%)
      scale(0.7);
  }


  .hotspot::before {
    content: "";

    position: absolute;

    top: 50%;
    left: 50%;

    width: 12px;
    height: 12px;

    border-radius: 50%;

    background:
      var(--dot-color, black);

    transform:
      translate(-50%, -50%);

    z-index: 4;

    box-shadow:
      0 0 0 5px
        var(--border-color, black),
      0 0 0 7px
        var(--dot-color, white);
  }


  .hotspot.active::before {

    background:
      var(--border-color, white);

    box-shadow:
      0 0 0 12px
        var(--dot-color, white),
      0 0 0 14px
        var(--border-color, black);

    height: 20px;
    width: 20px;
  }

  .panel-prev, .panel-next { 
    cursor: pointer;
  }

  /*
   * ---------------------------------------------------------
   * PANEL IMAGE
   * ---------------------------------------------------------
   */

  .panel-image img {
    width: 100%;

    @media (min-width: 768px) and (max-width: 1200px),
      (max-width: 767px) {

      height: 100%;
      object-fit: cover;
    }
  }


  /*
   * ---------------------------------------------------------
   * PANEL TITLE
   * ---------------------------------------------------------
   */

  .panel-title {
    font-size: 20px;
    font-weight: 700;

    margin-top: 12px;

    padding: 0px 20px;

    @media (min-width: 768px) and (max-width: 1200px),
      (max-width: 767px) {

      padding: 0px;
    }
  }


  /*
   * ---------------------------------------------------------
   * PANEL DESCRIPTION
   * ---------------------------------------------------------
   */

  .panel-desc {
    margin-top: 8px;

    padding: 0px 20px;

    @media (min-width: 768px) and (max-width: 1200px),
      (max-width: 767px) {

      padding: 0px;
    }
  }


  /*
   * ---------------------------------------------------------
   * PANEL IMAGE WRAPPER
   * ---------------------------------------------------------
   */

  .panel-image {
    position: relative;

    padding: 0px 20px;

    @media (min-width: 768px) and (max-width: 1200px),
      (max-width: 767px) {

      width: 100%;
      overflow: hidden;
      padding: 0px;
    }
  }


  /*
   * ---------------------------------------------------------
   * PANEL ANIMATION
   * ---------------------------------------------------------
   */

  .panel-image,
  .panel-title,
  .panel-desc {

    transition:
      opacity 0.25s ease,
      transform 0.25s ease;
  }


  .panel-transition-out {

    opacity: 0;

    transform:
      translateY(10px);
  }


  .panel-transition-in {

    opacity: 1;

    transform:
      translateY(0);
  }


  .panel-content-animate {

    transform:
      translateY(20px);

    opacity: 0;
  }


  .panel-content-show {

    transform:
      translateY(0);

    opacity: 1;

    transition:
      all 0.2s ease;
  }


  /*
   * ---------------------------------------------------------
   * PANEL ARROWS
   * ---------------------------------------------------------
   */

  .panel-arrows {

    position: absolute;

    top: 50%;
    left: 0;
    right: 0;

    padding: 0px 20px;

    display: flex;

    justify-content: space-between;

    transform:
      translateY(-50%);

    z-index: 5;

    @media (min-width: 768px) and (max-width: 1200px),
      (max-width: 767px) {

      padding: 0px;
    }
  }


  .panel-arrows button {

    background:
      rgba(255, 255, 255, 0.6);

    border: none;

    width: 40px;
    height: 40px;

    border-radius: 50%;

    cursor: pointer;
  }


  /*
   * ---------------------------------------------------------
   * PANEL DOTS
   * ---------------------------------------------------------
   */

  .panel-dots {

    display: flex;

    gap: 20px;

    margin: 15px 0;

    list-style: none;

    padding: 0px 20px;

    @media (min-width: 768px) and (max-width: 1200px),
      (max-width: 767px) {

      margin: 10px 0px;
      padding-left: 0px;
    }
  }


  .panel-dots li {

    width: 15px;
    height: 15px;

    cursor: pointer;

    background: #eaeaec;
  }


  .panel-dots li.active {
    background: black;
  }


  /*
   * ---------------------------------------------------------
   * PANEL CLOSE
   * ---------------------------------------------------------
   */

  .panel-close {

    position: absolute;

    right: 8px;

    background: #fff;

    border: none;

    width: 25px;
    height: 25px;

    font-size: 20px;

    cursor: pointer;

    z-index: 10;

    font-weight: 800;

    @media (min-width: 768px) and (max-width: 1200px) {

      top: 1px;
      right: 0px;
      left: 96%;

      background:
        rgba(255, 255, 255);

      border: none;

      width: 35px;
      height: 35px;

      font-size: 23px;

      z-index: 10000;
    }


    @media (max-width: 767px) {

      top: 1px;
      right: 0px;
      left: 91.6%;

      background:
        rgba(255, 255, 255);

      border: none;

      width: 35px;
      height: 35px;

      z-index: 10000;

      font-size: 22px;
    }
  }


  .panel-close:hover {
    background: #eee;
  }


  /*
   * ---------------------------------------------------------
   * CHEVRON ICONS
   * ---------------------------------------------------------
   */

  .icon-Chevron-Left {

    font-weight: 800;
    font-size: 22px;

    @media (min-width: 768px) and (max-width: 1200px) {
      font-size: 26px;
    }

    @media (max-width: 767px) {
      font-size: 24px;
    }
  }


  .icon-Chevron-Right {

    font-weight: 800;
    font-size: 22px;

    @media (min-width: 768px) and (max-width: 1200px) {
      font-size: 26px;
    }

    @media (max-width: 767px) {
      font-size: 24px;
    }
  }


  img {
    width: 100%;
  }
}

